/// Get indices where array values are not equal to zero
///
/// The most basic use is to convert a mask into a list of indices.
/// ex: ⊚ [1 0 0 1 0 1 1 0]
/// ex: ⊸⊚ =0⊸◿3 [1 0 2 9 3 8 3 4 6]
/// It also works for counts `greater than` 1.
/// ex: ⊚ 1_2_3
/// ex: ⊚ 1_4_2
/// [where] on a list is equivalent to `backward``keep``un``select`
/// ex:    ⊚ [0 1 0 0 2 0 1]
/// ex: ˜▽°⊏ [0 1 0 0 2 0 1]
///
/// [un][where] will convert the indices back into a list of counts
/// ex: °⊚ [0 0 0 1 1 2 2 2 2 2 3]
/// The indices need not be in order
/// ex: °⊚ [0 1 2 2 0 3 2 1 2 0 2]
///
/// [where] can be used on multidimensional arrays, and the result will always be rank-2
/// ex: ⊸⊚ [1_0_0 0_1_1 0_2_0]
/// The inverse works as well
/// ex: °⊚ [3_4 2_1 0_3]
///
/// [where] on a scalar is equivalent to [where] on a singleton array of that scalar, and so creates a list of `0`s.
/// ex: ⊚3
/// ex: ⊚8
(1, Where, MonadicArray, ("where", '⊚')),

impl Value {
    /// Get the indices `where` the value is nonzero
    pub fn wher(&self, env: &Uiua) -> UiuaResult<Value> {
        let counts =
            self.as_natural_array(env, "Argument to where must be an array of naturals")?;
        let total: usize = counts.data.iter().fold(0, |acc, &b| acc.saturating_add(b));
        let mut val: Value = match self.rank() {
            0 => {
                validate_size::<u8>([total], env)?;
                let data = eco_vec![0u8; total];
                let mut arr = Array::new([total], data);
                arr.meta.mark_sorted_down(true);
                arr.into()
            }
            1 => {
                validate_size::<f64>([total], env)?;
                let mut data = EcoVec::with_capacity(total);
                for (i, &b) in counts.data.iter().enumerate() {
                    let i = i as f64;
                    for _ in 0..b {
                        data.push(i);
                    }
                }
                Array::from(data).into()
            }
            _ => {
                validate_size::<f64>([total, counts.rank()], env)?;
                let mut data = EcoVec::with_capacity(total * counts.rank());
                for (i, &b) in counts.data.iter().enumerate() {
                    for _ in 0..b {
                        let mut i = i;
                        let start = data.len();
                        for &d in counts.shape.iter().rev() {
                            data.insert(start, (i % d) as f64);
                            i /= d;
                        }
                    }
                }
                let shape = Shape::from([total, counts.rank()].as_ref());
                Array::new(shape, data).into()
            }
        };
        val.meta.mark_sorted_up(true);
        val.validate();
        Ok(val)
    }

